import{_ as s,o as a,c as o,ag as t}from"./chunks/framework.D2veAa-g.js";const g=JSON.parse('{"title":"NoSQL数据库","description":"","frontmatter":{"title":"NoSQL数据库"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/数据库设计基础知识（第二版）/NoSQL数据库.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/数据库设计基础知识（第二版）/NoSQL数据库.md","lastUpdated":null}'),n={name:"架构师 在线刷题/51CT0题库 章节练习/数据库设计基础知识（第二版）/NoSQL数据库.md"};function i(e,l,r,c,u,d){return a(),o("div",null,[...l[0]||(l[0]=[t('<h1 id="nosql数据库" tabindex="-1">NoSQL数据库 <a class="header-anchor" href="#nosql数据库" aria-label="Permalink to &quot;NoSQL数据库&quot;">​</a></h1><blockquote><p>共 12 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-分布式数据库缓存技术有memcache与redis-关于两者的说法正确的是" tabindex="-1">Q1. 分布式数据库缓存技术有Memcache与Redis，关于两者的说法正确的是（） <a class="header-anchor" href="#q1-分布式数据库缓存技术有memcache与redis-关于两者的说法正确的是" aria-label="Permalink to &quot;Q1. 分布式数据库缓存技术有Memcache与Redis，关于两者的说法正确的是（）&quot;">​</a></h2><ul><li><strong>A.</strong> Memcache不仅仅支持简单的k/v类型的数据，同时还提供list，set，hash等数据结构的存储。</li><li><strong>B.</strong> Redis支持多线程</li><li><strong>C.</strong> Memcache不能进行内存管理</li><li><strong>D.</strong> Redis支持主从、sentinel、cluster等分布式存储方式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q2-以下不属于nosql数据库分类的是-。" tabindex="-1">Q2. 以下不属于NoSQL数据库分类的是 （ ） 。 <a class="header-anchor" href="#q2-以下不属于nosql数据库分类的是-。" aria-label="Permalink to &quot;Q2. 以下不属于NoSQL数据库分类的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 列式存储数据库</li><li><strong>B.</strong> 键值对存储数据库</li><li><strong>C.</strong> 关系型数据库</li><li><strong>D.</strong> 图数据库</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q3-nosql数据库的分类中-最适合用于存储社交网络中的用户关系图谱-如朋友列表和关注者。" tabindex="-1">Q3. NoSQL数据库的分类中， （ ） 最适合用于存储社交网络中的用户关系图谱，如朋友列表和关注者。 <a class="header-anchor" href="#q3-nosql数据库的分类中-最适合用于存储社交网络中的用户关系图谱-如朋友列表和关注者。" aria-label="Permalink to &quot;Q3. NoSQL数据库的分类中， （ ） 最适合用于存储社交网络中的用户关系图谱，如朋友列表和关注者。&quot;">​</a></h2><ul><li><strong>A.</strong> 键值存储</li><li><strong>B.</strong> 文档存储</li><li><strong>C.</strong> 列族存储</li><li><strong>D.</strong> 图数据库</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q4-关于nosql的数据一致性-正确的是-。" tabindex="-1">Q4. 关于NoSQL的数据一致性，正确的是 （ ） 。 <a class="header-anchor" href="#q4-关于nosql的数据一致性-正确的是-。" aria-label="Permalink to &quot;Q4. 关于NoSQL的数据一致性，正确的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 默认满足强一致性</li><li><strong>B.</strong> 通常提供最终一致性</li><li><strong>C.</strong> 不支持任何一致性模型</li><li><strong>D.</strong> 与关系型数据库一致</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q5-在以下哪种情况下-使用nosql数据库最为合适-。" tabindex="-1">Q5. 在以下哪种情况下，使用NoSQL数据库最为合适（ ）。 <a class="header-anchor" href="#q5-在以下哪种情况下-使用nosql数据库最为合适-。" aria-label="Permalink to &quot;Q5. 在以下哪种情况下，使用NoSQL数据库最为合适（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 需要高度的数据一致性</li><li><strong>B.</strong> 数据模型复杂且需要严格的关系结构</li><li><strong>C.</strong> 系统对数据库性能要求较高</li><li><strong>D.</strong> 需要支持复杂的事务处理</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q6-nosql框架的四层结构中-哪一层定义了数据的存储形式-。" tabindex="-1">Q6. NOSQL框架的四层结构中，哪一层定义了数据的存储形式（ ）。 <a class="header-anchor" href="#q6-nosql框架的四层结构中-哪一层定义了数据的存储形式-。" aria-label="Permalink to &quot;Q6. NOSQL框架的四层结构中，哪一层定义了数据的存储形式（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 数据分布层</li><li><strong>B.</strong> 数据持久层</li><li><strong>C.</strong> 数据逻辑模型层</li><li><strong>D.</strong> 接口层</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q7-某公司正在开发一个社交网络应用-需要选择一种适合存储和处理复杂关系数据的数据库。根据nosql数据库的特点-以下哪种类型最适合该应用场景-。" tabindex="-1">Q7. 某公司正在开发一个社交网络应用，需要选择一种适合存储和处理复杂关系数据的数据库。根据NoSQL数据库的特点，以下哪种类型最适合该应用场景（ ）。 <a class="header-anchor" href="#q7-某公司正在开发一个社交网络应用-需要选择一种适合存储和处理复杂关系数据的数据库。根据nosql数据库的特点-以下哪种类型最适合该应用场景-。" aria-label="Permalink to &quot;Q7. 某公司正在开发一个社交网络应用，需要选择一种适合存储和处理复杂关系数据的数据库。根据NoSQL数据库的特点，以下哪种类型最适合该应用场景（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 文档存储</li><li><strong>B.</strong> 键值存储</li><li><strong>C.</strong> 列存储</li><li><strong>D.</strong> 图存储</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q8-根据nosql数据库的存储方式分类-以下哪种类型主要用于社交网络和推荐系统等需要构建系统图谱的场景-。" tabindex="-1">Q8. 根据NoSQL数据库的存储方式分类，以下哪种类型主要用于社交网络和推荐系统等需要构建系统图谱的场景（ ）。 <a class="header-anchor" href="#q8-根据nosql数据库的存储方式分类-以下哪种类型主要用于社交网络和推荐系统等需要构建系统图谱的场景-。" aria-label="Permalink to &quot;Q8. 根据NoSQL数据库的存储方式分类，以下哪种类型主要用于社交网络和推荐系统等需要构建系统图谱的场景（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 文档存储</li><li><strong>B.</strong> 键值存储</li><li><strong>C.</strong> 列存储</li><li><strong>D.</strong> 图存储</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q9-关于文档型数据库-如mongodb-的描述-以下正确的是-。" tabindex="-1">Q9. 关于文档型数据库（如MongoDB）的描述，以下正确的是 （ ） 。 <a class="header-anchor" href="#q9-关于文档型数据库-如mongodb-的描述-以下正确的是-。" aria-label="Permalink to &quot;Q9. 关于文档型数据库（如MongoDB）的描述，以下正确的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 以JSON/BSON等格式存储数据，一个文档即一个数据单元</li><li><strong>B.</strong> 不支持嵌套结构，所有数据必须扁平化</li><li><strong>C.</strong> 数据必须以严格的二维表结构存储</li><li><strong>D.</strong> 擅长处理实体间复杂的多对多关系查询</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q10-请详细阅读有关数据库方面的描述-回答问题。【说明】某软件公司欲开发一个基于web-2-0的大型社交网络系统。就该系统的数据架构而言-李工决定采用公司熟悉的数据架构-使用通用的商用关系型数据库-系统内部数据采用中央集中方式存储。该系统投入使用后-初期用户数量少-系统运行平稳。6个月后-用户数出现了爆炸式增长-系统暴露出诸多问题-集中表现在-1-用户执行读写操作时-响应时间均变得很慢-2-随着系统功能的扩充-原有数据格式发生变化-又出现新的数据格式-维护困难-3-数据容量很快超过系统原有的设计上限-数据库扩容困难-4-软件系统不断出现宕机-整个系统可用性较差。经过多次会议讨论-公司的邹月平邹工建议采用nosql数据库来替代关系数据库-以解决上述问题。但薛大龙薛工指出nosql数据库出现时间不长-在使用上可能存在风险。公司技术人员对nosql数据库产品进行了认真测试-最终决定采用nosql数据库来替代现有的数据库系统。【问题1】10分请比较关系数据库与-nosql-数据的特点-如表-4-1-所示-以此来说明该系统更适合采用-nosql-数据库。请完成表-4-1-中的-1-5-处空白。表-4-1-关系数据库与-nosql-数据库特征比较【问题2】15分公司最终决定采用邹工的方案-同时配合分布式缓存技术减轻数据库服务器压力-目前有memcache和redis两种方案-请从数据类型、持久化和分布式存储三个方面比较两种技术的区别。" tabindex="-1">Q10. 请详细阅读有关数据库方面的描述，回答问题。【说明】某软件公司欲开发一个基于Web 2.0的大型社交网络系统。就该系统的数据架构而言，李工决定采用公司熟悉的数据架构，使用通用的商用关系型数据库，系统内部数据采用中央集中方式存储。该系统投入使用后，初期用户数量少，系统运行平稳。6个月后，用户数出现了爆炸式增长，系统暴露出诸多问题，集中表现在：1.用户执行读写操作时，响应时间均变得很慢；2.随着系统功能的扩充，原有数据格式发生变化，又出现新的数据格式，维护困难；3.数据容量很快超过系统原有的设计上限，数据库扩容困难；4.软件系统不断出现宕机，整个系统可用性较差。经过多次会议讨论，公司的邹月平邹工建议采用NoSQL数据库来替代关系数据库，以解决上述问题。但薛大龙薛工指出NoSQL数据库出现时间不长，在使用上可能存在风险。公司技术人员对NoSQL数据库产品进行了认真测试，最终决定采用NoSQL数据库来替代现有的数据库系统。【问题1】10分请比较关系数据库与 NoSQL 数据的特点，如表 4-1 所示，以此来说明该系统更适合采用 NoSQL 数据库。请完成表 4-1 中的（1） ~ （5） 处空白。表 4-1 关系数据库与 NoSQL 数据库特征比较【问题2】15分公司最终决定采用邹工的方案，同时配合分布式缓存技术减轻数据库服务器压力，目前有Memcache和Redis两种方案，请从数据类型、持久化和分布式存储三个方面比较两种技术的区别。 <a class="header-anchor" href="#q10-请详细阅读有关数据库方面的描述-回答问题。【说明】某软件公司欲开发一个基于web-2-0的大型社交网络系统。就该系统的数据架构而言-李工决定采用公司熟悉的数据架构-使用通用的商用关系型数据库-系统内部数据采用中央集中方式存储。该系统投入使用后-初期用户数量少-系统运行平稳。6个月后-用户数出现了爆炸式增长-系统暴露出诸多问题-集中表现在-1-用户执行读写操作时-响应时间均变得很慢-2-随着系统功能的扩充-原有数据格式发生变化-又出现新的数据格式-维护困难-3-数据容量很快超过系统原有的设计上限-数据库扩容困难-4-软件系统不断出现宕机-整个系统可用性较差。经过多次会议讨论-公司的邹月平邹工建议采用nosql数据库来替代关系数据库-以解决上述问题。但薛大龙薛工指出nosql数据库出现时间不长-在使用上可能存在风险。公司技术人员对nosql数据库产品进行了认真测试-最终决定采用nosql数据库来替代现有的数据库系统。【问题1】10分请比较关系数据库与-nosql-数据的特点-如表-4-1-所示-以此来说明该系统更适合采用-nosql-数据库。请完成表-4-1-中的-1-5-处空白。表-4-1-关系数据库与-nosql-数据库特征比较【问题2】15分公司最终决定采用邹工的方案-同时配合分布式缓存技术减轻数据库服务器压力-目前有memcache和redis两种方案-请从数据类型、持久化和分布式存储三个方面比较两种技术的区别。" aria-label="Permalink to &quot;Q10. 请详细阅读有关数据库方面的描述，回答问题。【说明】某软件公司欲开发一个基于Web 2.0的大型社交网络系统。就该系统的数据架构而言，李工决定采用公司熟悉的数据架构，使用通用的商用关系型数据库，系统内部数据采用中央集中方式存储。该系统投入使用后，初期用户数量少，系统运行平稳。6个月后，用户数出现了爆炸式增长，系统暴露出诸多问题，集中表现在：1.用户执行读写操作时，响应时间均变得很慢；2.随着系统功能的扩充，原有数据格式发生变化，又出现新的数据格式，维护困难；3.数据容量很快超过系统原有的设计上限，数据库扩容困难；4.软件系统不断出现宕机，整个系统可用性较差。经过多次会议讨论，公司的邹月平邹工建议采用NoSQL数据库来替代关系数据库，以解决上述问题。但薛大龙薛工指出NoSQL数据库出现时间不长，在使用上可能存在风险。公司技术人员对NoSQL数据库产品进行了认真测试，最终决定采用NoSQL数据库来替代现有的数据库系统。【问题1】10分请比较关系数据库与 NoSQL 数据的特点，如表 4-1 所示，以此来说明该系统更适合采用 NoSQL 数据库。请完成表 4-1 中的（1） ~ （5） 处空白。表 4-1 关系数据库与 NoSQL 数据库特征比较【问题2】15分公司最终决定采用邹工的方案，同时配合分布式缓存技术减轻数据库服务器压力，目前有Memcache和Redis两种方案，请从数据类型、持久化和分布式存储三个方面比较两种技术的区别。&quot;">​</a></h2><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong><p>见解析</p></strong></p></div></details><h2 id="q11-问题一-9分-在研讨过程中-设备厂商的技术总监提出采用互联网公司常用的ssm架构-使用mysql作为数据库-而软件研发团队的架构师却提出要使用由mysql、hbase和redis组成的多种多组数据库。请给出适当建议。" tabindex="-1">Q11. 问题一（9分）：在研讨过程中，设备厂商的技术总监提出采用互联网公司常用的SSM架构，使用MySQL作为数据库，而软件研发团队的架构师却提出要使用由MySQL、HBase和Redis组成的多种多组数据库。请给出适当建议。 <a class="header-anchor" href="#q11-问题一-9分-在研讨过程中-设备厂商的技术总监提出采用互联网公司常用的ssm架构-使用mysql作为数据库-而软件研发团队的架构师却提出要使用由mysql、hbase和redis组成的多种多组数据库。请给出适当建议。" aria-label="Permalink to &quot;Q11. 问题一（9分）：在研讨过程中，设备厂商的技术总监提出采用互联网公司常用的SSM架构，使用MySQL作为数据库，而软件研发团队的架构师却提出要使用由MySQL、HBase和Redis组成的多种多组数据库。请给出适当建议。&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题三国内某安防公司欲为其防火报警器产品研发互联网产品以提高产品的易用性和用户透明性，并为主管部门提供信息辅助和联防联控支持。据用户描述，设备使用场景存在多种可能性，如：1. 开发商集中采购在楼盘中批量安装部署；2. 用户购买，在自身房屋中安装使用1个到多个终端；3. 企业在其自身的营业场所批量安装部署；并且，研发的应用产品将面对多种使用客户，如：1. 消防中队或消防站2. 企业安防用户3. 社区或物业的安防用户4. 个人用户及其亲属关联用户据此，系统分析师提出以SaaS产品形式组织应用研发。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>技术总监的建议中，MySQL属于关系型数据库，实际应用中一般用来作为操作数据存储。研发架构师提出的HBase和Redis属于NoSQL，实际应用中一般用来做大数据量和高即时性数据存储。该案例属于物联网应用，建议增加NoSQL数据库提高数据存储的容量和即时性。但是HBase属于列族数据库，不便于关联数据的查询，既降低查询速度，又增加IO操作，建议采用MongoDB替换掉HBase。</p></div></details><h2 id="q12-【问题1】-8分-请完成表4-1中的-a-d-处空白。表4-1关系数据库与nosql数据库特征比较" tabindex="-1">Q12. 【问题1】（8分）请完成表4-1中的（a）～（d）处空白。表4-1关系数据库与NoSQL数据库特征比较 <a class="header-anchor" href="#q12-【问题1】-8分-请完成表4-1中的-a-d-处空白。表4-1关系数据库与nosql数据库特征比较" aria-label="Permalink to &quot;Q12. 【问题1】（8分）请完成表4-1中的（a）～（d）处空白。表4-1关系数据库与NoSQL数据库特征比较&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题四请详细阅读有关数据架构方面的描述，回答问题。【说明】某软件公司欲开发一个基于Web 2.0的大型社交网络系统。就该系统的数据架构而言，李工决定采用公司熟悉的数据架构，使用通用的商用关系型数据库，系统内部数据采用中央集中方式存储。该系统投入使用后，初期用户数量少，系统运行平稳。6个月后，用户数出现了爆炸式增长，系统暴露出诸多问题，集中表现在：1.用户执行读写操作时，响应时间均变得很慢；2.随着系统功能的扩充，原有数据格式发生变化，又出现新的数据格式，维护困难；3.数据容量很快超过系统原有的设计上限，数据库扩容困难；4.软件系统不断出现宕机，整个系统可用性较差。经过多次会议讨论，公司的王工建议采用NoSQL数据库来替代关系数据库，以解决上述问题。但李工指出NoSQL数据库出现时间不长，在使用上可能存在风险。公司技术人员对NoSQL数据库产品进行了认真测试，最终决定采用NoSQL数据库来替代现有的数据库系统。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>（a）弱一致性（b）非结构化（c）弱事务性（d）海量数据</p></div></details>',37)])])}const q=s(n,[["render",i]]);export{g as __pageData,q as default};
